import React from "react";
import { motion } from "framer-motion";
import { Sparkles, TrendingUp, Calendar } from "lucide-react";

const SEASONS = [
  {
    name: "Summer Wedding Collection",
    desc: "Light fabrics in pastels and vibrant colors",
    colors: ["#DE8F9C", "#F7E7CE", "#78A2CC"],
    badge: "Trending Now"
  },
  {
    name: "Monsoon Magic",
    desc: "Rich velvets and monsoon-inspired hues",
    colors: ["#722F37", "#1a080a", "#d4af37"],
    badge: "New Arrival"
  },
  {
    name: "Winter Wonderland",
    desc: "Luxurious velvets and metallic accents",
    colors: ["#C0C0C0", "#800020", "#1a1a3e"],
    badge: "Premium"
  },
  {
    name: "Spring Celebration",
    desc: "Floral patterns and fresh hues",
    colors: ["#046307", "#DE8F9C", "#B76E79"],
    badge: "Popular"
  },
];

export default function SeasonalCollections() {
  return (
    <section className="py-20 md:py-28" style={{ background: "linear-gradient(180deg, #ffffff 0%, #fff9ed 100%)" }}>
      <div className="px-6 md:px-12 lg:px-24">

        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-12"
        >
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full mb-4" style={{ background: "rgba(212,175,55,0.1)", border: "1px solid rgba(212,175,55,0.2)" }}>
            <Sparkles size={16} color="#d4af37" />
            <span className="text-xs uppercase tracking-wider" style={{ color: "#d4af37" }}>New Arrivals</span>
          </div>

          <h2 className="serif text-3xl md:text-4xl mb-4" style={{ color: "#1a080a" }}>
            Seasonal <span style={{ color: "#d4af37", fontStyle: "italic" }}>Collections</span>
          </h2>

          <p className="text-base max-w-xl mx-auto" style={{ color: "rgba(26,8,10,0.6)" }}>
            Trend-driven selections curated for current market demand. Stay ahead with our latest fabric collections.
          </p>
        </motion.div>

        {/* Collections Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {SEASONS.map((season, i) => (
            <motion.div
              key={season.name}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              whileHover={{ y: -8 }}
              className="relative rounded-2xl overflow-hidden cursor-pointer"
              style={{ background: "white", border: "1px solid rgba(212,175,55,0.2)", boxShadow: "0 4px 20px rgba(212,175,55,0.08)" }}
            >
              {/* Color Palette Preview */}
              <div className="h-32 flex items-center justify-center gap-2" style={{ background: "linear-gradient(135deg, rgba(212,175,55,0.05), rgba(212,175,55,0.02)" }}>
                {season.colors.map((color, ci) => (
                  <div
                    key={ci}
                    className="w-12 h-12 rounded-full"
                    style={{ background: color, boxShadow: "0 2px 8px rgba(0,0,0,0.15)" }}
                  />
                ))}
              </div>

              {/* Badge */}
              <div className="absolute top-3 right-3">
                <span className="px-3 py-1 rounded-full text-xs font-semibold" style={{ background: "#d4af37", color: "white" }}>
                  <TrendingUp size={12} className="inline mr-1" />
                  {season.badge}
                </span>
              </div>

              {/* Content */}
              <div className="p-5">
                <h3 className="text-lg font-semibold mb-2" style={{ color: "#1a080a" }}>{season.name}</h3>
                <p className="text-sm mb-4" style={{ color: "rgba(26,8,10,0.6)" }}>{season.desc}</p>

                <button
                  onClick={() => window.open(`https://wa.me/919888919983?text=Hi!%20I'm%20interested%20in%20${encodeURIComponent(season.name)}`, "_blank")}
                  className="w-full py-2 rounded-full text-sm font-medium transition-all"
                  style={{ background: "rgba(212,175,55,0.1)", color: "#d4af37", border: "1px solid rgba(212,175,55,0.3)" }}
                >
                  Enquire Now
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* All Year Availability */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="mt-12 text-center"
        >
          <div className="inline-flex items-center gap-3 px-6 py-4 rounded-full" style={{ background: "white", border: "1px solid rgba(212,175,55,0.3)", boxShadow: "0 4px 20px rgba(212,175,55,0.1)" }}>
            <Calendar size={20} color="#d4af37" />
            <span className="text-sm" style={{ color: "#1a080a" }}>
              <strong>Available Year-Round</strong> - Custom orders welcome for any season
            </span>
          </div>
        </motion.div>
      </div>
    </section>
  );
}
